import {uid,day,scaled,money,qty,balance,currentSession,expectedCash,emptyState,transact,metrics,demoState} from './core.js';
import {openDB,read,save} from './db.js';
import {openPhotos,photoOf,savePhoto,removePhoto,shrinkPhoto} from './photos.js';
import {online,cloudUser,setCloudUser,cloudToken,cloudAccept,cloudForget,pendingCommand,clearPending,cloudCall,cloudCommand} from './cloud.js';
const $=s=>document.querySelector(s),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',cart:'M3 3h2l3 13h11l2-9H6M9 20h.01M18 20h.01',box:'m3 7 9-4 9 4v10l-9 4-9-4ZM3 7l9 4 9-4M12 11v10M7 5l10 4',truck:'M3 5h11v12H3zM14 9h4l3 4v4h-7M7 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4M17 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M18 3a4 4 0 0 1 0 7M22 21v-3a4 4 0 0 0-3-4',wallet:'M20 8V5H4a2 2 0 0 0 0 4h17v11H4a2 2 0 0 1-2-2V7M21 12h-6v5h6M17 14.5h.01',chart:'M4 3v18h17M8 15l4-5 4 2 5-8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',down:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16',check:'m5 12 4 4L19 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',grain:'M12 22V3M12 9C6 9 5 5 5 2c5 0 7 3 7 7ZM12 16c-6 0-7-4-7-7 5 0 7 3 7 7ZM12 12c6 0 7-4 7-7-5 0-7 3-7 7ZM12 19c6 0 7-4 7-7-5 0-7 3-7 7Z',close:'M6 6l12 12M18 6 6 18',menu:'M3 6h18M3 12h18M3 18h18',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',store:'M3 10V5h18v5M5 10v11h14V10M8 21v-7h8v7M2 10c0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0',receipt:'M5 3h14v19l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h4',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6ZM8 12l3 3 5-6',minus:'M5 12h14',trash:'M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3',cash:'M3 6h18v12H3zM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6M6.5 9.5h.01M17.5 14.5h.01',phone:'M7 2h10v20H7zM11 18h2',bank:'M3 10l9-6 9 6M5 10v8M9.5 10v8M14.5 10v8M19 10v8M3 21h18',book:'M5 3h12a2 2 0 0 1 2 2v16H7a2 2 0 0 1-2-2ZM5 17a2 2 0 0 1 2-2h12M9 7h6',split:'M12 3v18M4 8h5M4 13h5M15 11h5M15 16h5',camera:'M4 7h4l2-3h4l2 3h4v13H4zM12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',backspace:'M9 5h11v14H9l-6-7ZM12 9l5 6M17 9l-5 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.box}"/></svg>`;
const button=(label,action,kind='',ico='',attrs='')=>`<button class="btn ${kind}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const field=(label,name,type='text',value='',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;
const select=(label,name,options,value='')=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${v===value?'selected':''}>${e(l)}</option>`;}).join('')}</select></div>`;
const num=(label,name,value='0',step='.01',extra='')=>field(label,name,'number',value,`min="0" step="${step}" required ${extra}`);
const check=(label,name)=>`<div class="field"><label class="checkbox"><input type="checkbox" name="${name}">${label}</label></div>`;
const time=at=>new Date(at).toLocaleTimeString('en-PH',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'});
const date=at=>new Date(at).toLocaleDateString('en-PH',{timeZone:'Asia/Manila',month:'short',day:'numeric'});
const table=(headers,rows,empty='No records yet.')=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty">${empty}</div></td></tr>`}</tbody></table></div>`;
const row=cells=>`<tr>${cells.map(x=>`<td>${x}</td>`).join('')}</tr>`;
// The app opens on selling: that's what a cashier does all day.
const START_PAGE='pos',ALL_PRODUCTS='All products';
let db,photos,state,page=START_PAGE,cart=[],cartId=uid(),category=ALL_PRODUCTS,search='',held=null,busy=false,reportFrom=day(),reportTo=day();
// [page, icon, menu label, Tagalog hint]. Short words, because the menu is a slim icon rail.
const nav=[['pos','cart','Sell','Benta'],['dashboard','grid','Today','Ngayon'],['inventory','box','Stocks','Paninda'],['purchases','truck','Restock','Bili'],['customers','users','Utang','Listahan'],['cash','wallet','Cash','Kaha'],['reports','chart','Reports','Ulat'],['settings','settings','Settings','']];
// Sell screen settings.
const KILO_QUICK=[500,1000,2000,3000,5000,10000];   // grams offered as one-tap weights
const SACK_QUICK=[1,2,3,5];                        // sacks offered as one-tap amounts
const PAD_MAX_DECIMALS=3,PAD_MAX_LENGTH=7;          // keypad accepts up to 9999.999
const CASH_ROUND_UPS=[10000,50000,100000];         // centavos: suggest the next ₱100, ₱500 and ₱1,000
const TILE_TONES=4;                                // colors for products without a photo
const PAY_METHODS=[{value:'Cash',icon:'cash',label:'Cash',hint:'Pera'},{value:'GCash',icon:'phone',label:'GCash',hint:'E-wallet'},{value:'Maya',icon:'phone',label:'Maya',hint:'E-wallet'},{value:'Bank Transfer',icon:'bank',label:'Bank',hint:'Transfer'},{value:'Utang',icon:'book',label:'Utang',hint:'Listahan'},{value:'Split payment',icon:'split',label:'Split',hint:'Cash + e-wallet'}];
const DIGITAL_METHODS=['GCash','Maya','Bank Transfer'];
const count=n=>new Intl.NumberFormat('en-PH',{maximumFractionDigits:PAD_MAX_DECIMALS}).format(n);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function commit(type,data,id){if(online){const result=await cloudCommand(type,data,id,state.revision);state=result.state;setCloudUser(result.user);if(result.conflict)throw Error('Another device updated this store. The latest records are loaded; review the amount and retry.');return;}const next=transact(state,type,data,{id});await save(db,next,state.revision);state=next;}
const lowProducts=()=>state.products.filter(p=>p.stock<=p.minimum);
function stat(label,amount,desc,ico='wallet',emphasis=false){return `<div class="stat ${emphasis?'emphasis':''}"><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="amount">${amount}</div><small>${desc}</small></div>`;}
function head(title,sub,actions='',eye='YOUR STORE, IN VIEW'){return `<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function renderBase(){const title=nav.find(x=>x[0]===page)?.[2]||'Transaction history';$('#app').innerHTML=`<div class="shell"><aside class="sidebar rail"><div class="brand"><img src="icon.svg" alt="StorePOS"></div><nav class="nav" aria-label="Main navigation">${nav.map(([id,ico,label,local])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${local?`<small lang="tl">${local}</small>`:''}${id==='inventory'&&lowProducts().length?`<span class="badge" aria-label="${lowProducts().length} low on stock">${lowProducts().length}</span>`:''}</button>`).join('')}</nav><div class="owner" title="${e(state.store.owner)}"><span class="avatar">${e((state.store.owner||'Owner').slice(0,2).toUpperCase())}</span></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><strong class="store-name">${e(state.store.name)}</strong><span>/</span><span class="page-name">${title}</span></div><div class="top-actions"><span class="saved"><span class="dot"></span> Saved on this device</span><span class="top-date">${new Date().toLocaleDateString('en-PH',{timeZone:'Asia/Manila',month:'short',day:'numeric',year:'numeric'})}</span></div></header><div class="workspace ${page==='pos'?'pos-page':''}">${({dashboard,inventory,purchases,customers,cash,reports,settings,pos,history}[page]||dashboard)()}<footer class="footnote"><span>${state.demo?'Sample data · ':''}StorePOS Lite &nbsp; / &nbsp; Made for your everyday business</span><span>${currentSession(state)?'● Cash session open':'○ Cash session closed'} &nbsp; · &nbsp; Internal records only</span></footer></div></main></div>`;bind();}
function dashboard(){const m=metrics(state),low=lowProducts(),week=[];for(let i=6;i>=0;i--){const d=new Date();d.setUTCDate(d.getUTCDate()-i);week.push({label:d.toLocaleDateString('en-PH',{timeZone:'Asia/Manila',weekday:'short'}),value:metrics(state,day(d)).revenue});}const total=week.reduce((a,x)=>a+x.value,0),max=Math.max(...week.map(x=>x.value),10000);const points=week.map((x,i)=>`${45+i*77},${150-x.value/max*110}`).join(' ');const creditCustomers=state.customers.filter(c=>balance(state,c.id)>0).sort((a,b)=>balance(state,b.id)-balance(state,a.id));
 return head('A clear view of your business.',`Here’s how ${e(state.store.name)} is doing today.`,button('View reports','reports','secondary','chart')+button('New sale','pos','','plus'))+`<section class="welcome"><div><h2>Magandang araw, ${e(state.store.owner)} <span style="font-weight:400">☀</span></h2><p>A little clarity goes a long way. Keep track of your benta, stocks,<br class="desktop"> and every peso that comes in and out.</p><div class="welcome-note">${icon('check')} ${m.sales.length} sales recorded today &nbsp; · &nbsp; ${currentSession(state)?'Your store is ready for business':'Open your cash session to start selling'}</div></div><div class="welcome-mark">${icon('grain').replace('class="icon"','style="width:88px;height:88px;fill:none;stroke:currentColor;stroke-width:1"')}</div></section><div class="section-title"><h2>Today at a glance</h2><span class="period">${icon('calendar')} Today, ${date(new Date())}</span></div><section class="stats">${stat('Total sales / Benta',money(m.revenue),`${m.sales.length} completed transactions`,'cart',true)}${stat('Payments collected',money(m.collections),'Cash + verified digital payments','wallet')}${stat('Gross profit',money(m.profit),'Sales less recorded cost of goods','chart')}${stat('Operating expenses',money(m.expenses),'Keep the everyday costs in view','receipt')}</section><div class="middle-grid"><section class="panel"><div class="panel-head"><div><h2>Sales performance</h2><p>A little progress, every day.</p></div><span class="pill">Last 7 days</span></div><div class="panel-body"><div class="section-title"><div class="chart-total">${money(total)}</div><div class="legend"><span class="dot"></span> Sales / Benta</div></div><svg class="chart" viewBox="0 0 540 190" role="img" aria-label="Sales over the last seven days: ${week.map(x=>`${x.label} ${money(x.value)}`).join(', ')}"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#dce9cd" stop-opacity=".6"/><stop offset="1" stop-color="#f9fbf6" stop-opacity=".2"/></linearGradient></defs>${[0,1,2,3].map(i=>`<path class="grid" d="M42 ${40+i*37}H520"/><text x="0" y="${44+i*37}">${(max/100*(1-i/3)/1000).toFixed(1)}k</text>`).join('')}<polygon points="45,151 ${points} 507,151" fill="url(#fill)"/><polyline points="${points}" fill="none" stroke="#719251" stroke-width="2.5" stroke-linejoin="round"/>${week.map((x,i)=>`<circle cx="${45+i*77}" cy="${150-x.value/max*110}" r="3.5" fill="white" stroke="#719251" stroke-width="2"/><text text-anchor="middle" x="${45+i*77}" y="179">${x.label}</text>`).join('')}</svg></div></section><section class="panel"><div class="panel-head"><div><h2>A little stock check</h2><p>Let’s keep your shelves ready.</p></div><span class="pill warn">${low.length} low stock</span></div><div class="panel-body">${low.length?low.slice(0,3).map(p=>`<div class="stock-item"><div class="grain-icon">${icon('grain')}</div><div><strong>${e(p.name)}</strong><small>Minimum: ${qty(p.minimum)} kg</small></div><div class="stock-count"><strong>${qty(p.stock)} kg</strong><small>${p.stock?'Running low':'Out of stock'}</small></div></div>`).join(''):'<div class="empty">Your stocks are looking good.</div>'}<div class="row"><span>Cash on hand</span><strong>${money(m.cash)}</strong></div><div class="row"><span>Expected in your register</span>${button('Manage stock','inventory','ghost','arrow')}</div></div></section></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Recent transactions</h2><p>Every sale, accounted for.</p></div>${button('View all','history','ghost','arrow')}</div>${salesTable(state.sales.slice(-4).reverse(),true)}<div class="table-foot"><span>Amounts shown in Philippine pesos</span><span>${m.sales.length} sales today</span></div></section><section class="panel"><div class="panel-head"><div><h2>Customer credit / Utang</h2><p>A friendly reminder of what’s due.</p></div>${icon('users')}</div><div class="panel-body"><div class="credit-summary"><div><small>Total outstanding</small><div><strong>${money(m.credit)}</strong></div></div><span class="pill warn">${creditCustomers.length} customers</span></div>${creditCustomers.slice(0,3).map(c=>`<div class="stock-item"><span class="avatar">${e(c.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><div><strong>${e(c.name)}</strong><small>${overdue(c.id)?'Payment overdue':'Outstanding balance'}</small></div><div class="stock-count"><strong>${money(balance(state,c.id))}</strong></div></div>`).join('')}${button('Manage customer credit','customers','ghost','arrow')}</div></section></div>`;}
function saleDebt(sale){return state.ledger.filter(x=>x.saleId===sale.id).reduce((a,x)=>a+x.amount,0);}
function overdue(id){return state.sales.some(s=>s.customerId===id&&saleDebt(s)>0&&s.dueDate<day());}
function salesTable(sales,compact=false){return table(compact?['Transaction','Customer','Amount','Status']:['Transaction','Customer','Amount','Payment','Status',''],sales.map(s=>{const debt=saleDebt(s),status=s.refunded?'Refunded':debt===s.total&&debt?'Unpaid':debt?'Partially paid':'Paid',customer=state.customers.find(c=>c.id===s.customerId);const cells=[`<button class="text-link" data-action="receipt" data-id="${s.id}">${e(s.ref)}</button><small>${date(s.at)} · ${time(s.at)}</small>`,e(customer?.name||'Walk-in customer'),`<strong>${money(s.total)}</strong>`];if(!compact)cells.push([...new Set(state.payments.filter(p=>p.saleId===s.id&&p.kind==='Sale').map(p=>p.method))].join(' + ')||'Utang');cells.push(`<span class="pill ${debt?'warn':s.refunded?'red':''}">${status}</span>`);if(!compact)cells.push(s.refunded?'—':button('Refund','refund','secondary small','','data-id="'+s.id+'"'));return row(cells);}));}
function history(){return head('Transaction history','Every completed sale stays on record.',button('New sale','pos','','plus'))+`<section class="panel">${salesTable([...state.sales].reverse())}</section>`;}
function inventory(){const filtered=state.products.filter(p=>(p.name+' '+p.sku).toLowerCase().includes(search.toLowerCase()));return head('Products & inventory','Know what’s on the shelf, down to the last kilogram.',button('Stock history','movements','secondary','clock')+button('Add product','product','','plus'))+`<section class="stats">${stat('Products',state.products.length,'Rice varieties in your catalog','box')}${stat('Stock on hand',qty(state.products.reduce((a,p)=>a+p.stock,0))+' kg','All stock stored in base kilograms','grain')}${stat('Inventory value',money(state.products.reduce((a,p)=>a+p.stockValue,0)),'Weighted-average inventory cost','wallet')}${stat('Needs attention',lowProducts().length,'At or below minimum stock','box')}</section><div class="toolbar"><div class="search">${icon('search')}<input id="search" placeholder="Search name or SKU…" aria-label="Search products" value="${e(search)}"></div>${button('Export stock','export-stock','secondary','down')}</div><section class="panel">${table(['Product','Selling price','Average cost / kg','Stock','Sack size','Status',''],filtered.map(p=>row([`<div class="product-cell">${productThumb(p,'table-thumb')}<div><strong>${e(p.name)}</strong><small>${e(p.sku)} · ${e(p.category)}</small></div></div>`,`${money(p.price)} / kg<small>${money(p.sackPrice)} / sack</small>`,money(p.stock?Math.round(p.stockValue*1000/p.stock):p.cost),`<strong>${qty(p.stock)} kg</strong><small>Minimum ${qty(p.minimum)} kg</small>`,qty(p.sackGrams)+' kg',`<span class="pill ${p.stock<=p.minimum?'warn':''}">${p.stock===0?'Out of stock':p.stock<=p.minimum?'Low stock':'Available'}</span>`,button('Adjust','adjust','secondary small','','data-id="'+p.id+'"')+button(photoOf(photos,p.id)?'Photo':'Add photo','photo','secondary small','camera','data-id="'+p.id+'"')])) )}</section>`;}
function purchases(){return head('Purchases & restocking','Order in sacks. Receive in kilograms. Keep the costs clear.',button('New purchase','purchase','','plus'))+`<div class="notice green">Stock increases only when you receive a purchase. The new cost is combined with existing stock using weighted-average costing.</div><section class="panel">${table(['Supplier / Date','Product','Ordered quantity','Total cost','Status',''],[...state.purchases].reverse().map(p=>row([`<strong>${e(p.supplier)}</strong><small>${date(p.at)} · ${e(p.reference||'No supplier reference')}</small>`,e(p.productName),`${p.sacks} sacks × ${qty(p.sackGrams)} kg<small>${qty(p.quantity)} kg total</small>`,money(p.total),`<span class="pill ${p.receivedAt?'':'warn'}">${p.receivedAt?'Received':'Awaiting delivery'}</span>${p.receivedAt?`<small>${p.source==='Unpaid'?'Supplier balance unpaid':p.source+' payment'}</small>`:''}`,p.receivedAt?date(p.receivedAt):button('Receive stock','receive','small','','data-id="'+p.id+'"')])), 'No purchases yet. Create a purchase order when you’re ready to restock.')}</section>`;}
function customers(){return head('Customers & credit','A clearer utang notebook. Every payment in its proper place.',button('Add customer','customer','','plus'))+`<section class="stats">${stat('Outstanding credit',money(metrics(state).credit),'All customer balances','users',true)}${stat('Customers',state.customers.length,'Your neighborhood regulars','users')}${stat('Overdue customers',state.customers.filter(c=>overdue(c.id)).length,'Based on sale due dates','clock')}${stat('Collections today',money(state.payments.filter(x=>x.kind==='Collection'&&day(x.at)===day()).reduce((a,x)=>a+x.amount,0)),'Debt payments, not new sales','wallet')}</section><section class="panel">${table(['Customer','Outstanding','Credit limit','Status',''],state.customers.map(c=>row([`<strong>${e(c.name)}</strong><small>${e(c.phone||'No contact number')}</small>`,`<strong>${money(balance(state,c.id))}</strong>`,c.limit?money(c.limit):'No limit',`<span class="pill ${overdue(c.id)?'warn':''}">${overdue(c.id)?'Overdue':balance(state,c.id)?'Has balance':'All settled'}</span>`,`<div class="actions">${button('Statement','statement','secondary small','','data-id="'+c.id+'"')}${balance(state,c.id)?button('Collect','collection','small','','data-id="'+c.id+'"'):''}</div>`])) )}</section>`;}
function cash(){const session=currentSession(state),m=metrics(state);return head('Cash & expenses','Bilang ng pera. Know what should be in your cash box.',button('Record expense','expense','secondary','plus')+button(session?'Close session':'Open session',session?'close':'open','','wallet'))+`<section class="stats">${stat('Expected cash',money(expectedCash(state)),'Physical cash in the open session','wallet',true)}${stat('Opening float',money(session?.opening||0),session?'Opened '+date(session.openedAt)+' · '+time(session.openedAt):'No open cash session','store')}${stat('Expenses today',money(m.expenses),'Operating costs, all sources','receipt')}${stat('Digital collections',money(state.payments.filter(x=>day(x.at)===day()&&x.method!=='Cash').reduce((a,x)=>a+x.amount,0)),'Excluded from physical cash','wallet')}</section><div class="two-col"><section class="panel"><div class="panel-head"><h2>Cash movements</h2>${button('Cash in / out','cash-move','ghost','plus')}</div>${table(['Description','Date','Amount'],[...state.cashMoves].reverse().slice(0,10).map(x=>row([e(x.reason),date(x.at),money(x.amount)])))}</section><section class="panel"><div class="panel-head"><h2>Operating expenses</h2></div>${table(['Description','Source','Amount'],[...state.expenses].reverse().slice(0,10).map(x=>row([`<strong>${e(x.description)}</strong><small>${e(x.category)} · ${date(x.at)}</small>`,e(x.source),money(x.amount)])))}</section></div><section class="panel spacer"><div class="panel-head"><h2>Daily closing history</h2></div>${table(['Opened','Closed','Expected','Actual','Difference','Note'],[...state.sessions].filter(x=>x.closedAt).reverse().map(x=>row([date(x.openedAt),date(x.closedAt)+' · '+time(x.closedAt),money(x.expected),money(x.actual),`<span class="pill ${x.variance?'warn':''}">${money(x.variance)}</span>`,e(x.reason||'Balanced')])) )}</section>`;}
function reports(){const m=metrics(state,reportFrom,reportTo);const best=state.products.map(p=>{const lines=m.sales.filter(s=>!s.refunded).flatMap(s=>s.items).filter(x=>x.productId===p.id);return {name:p.name,quantity:lines.reduce((a,x)=>a+x.quantity,0),revenue:lines.reduce((a,x)=>a+x.revenue,0)};}).filter(p=>p.quantity).sort((a,b)=>b.quantity-a.quantity);return head('Business reports','Sales, collections, and profit — each tells a different story.',button('Export sales CSV','export-sales','secondary','down'))+`<div class="report-filters">${field('From','from','date',reportFrom,'id="report-from"')}${field('To','to','date',reportTo)}${button('Apply dates','filter-reports')}</div><section class="stats">${stat('Net sales',money(m.revenue),'Sales less refunds in this period','cart',true)}${stat('Gross profit',money(m.profit),'Net sales minus cost of goods','chart')}${stat('Operating profit',money(m.net),'Gross profit minus expenses','wallet')}${stat('Collections',money(m.collections),'Includes payments on old utang','wallet')}</section><div class="two-col"><section class="panel list-panel"><h2>Profit breakdown</h2>${[['Net sales',m.revenue],['Cost of goods sold',m.cost],['Gross profit',m.profit],['Operating expenses',m.expenses],['Estimated operating profit',m.net]].map(([l,n])=>`<div class="row"><span>${l}</span><strong>${money(n)}</strong></div>`).join('')}<p class="subtitle">Inventory losses affect stock value; this pilot’s operating profit does not yet include a separate inventory-loss expense.</p></section><section class="panel"><div class="panel-head"><h2>Best-selling products</h2></div>${table(['Product','Quantity','Before discounts'],best.map(p=>row([e(p.name),qty(p.quantity)+' kg',money(p.revenue)])))}<div class="table-foot">Fully refunded sales are excluded from this product ranking.</div></section></div><section class="panel spacer"><div class="panel-head"><h2>Sales in this period</h2></div>${salesTable([...m.sales].reverse())}</section>`;}
function settings(){return head('Your store, your way','A simple starting point for your business.')+`<div class="notice">This is a single-device pilot. Owner access is not a secure cashier permission system. Use sample records while testing; this version is not ready for live business or tax invoicing.</div><div class="two-col"><section class="panel list-panel"><h2>Store profile</h2><div class="row"><span>Name</span><strong>${e(state.store.name)}</strong></div><div class="row"><span>Owner</span><strong>${e(state.store.owner)}</strong></div><div class="row"><span>Address</span><strong>${e(state.store.address||'Not set')}</strong></div><div class="row"><span>Currency / Time zone</span><strong>PHP / Asia–Manila</strong></div><div class="spacer">${button('Edit store profile','profile','secondary')}</div></section><section class="panel list-panel"><h2>Keep your records safe</h2><p class="subtitle">Records are stored in this browser’s database. Clearing browser data removes them. Download a backup regularly and before changing devices.</p><div class="row"><span>Complete store backup</span>${button('Download JSON','backup','secondary small','down')}</div><div class="row"><span>Restore a StorePOS backup</span>${button('Restore','restore','secondary small')}</div><div class="row"><span>Recorded owner activity</span>${button('View audit trail','audit','secondary small')}</div></section><section class="panel list-panel"><h2>Start your own store</h2><p class="subtitle">The guided setup creates an empty store after downloading the current store backup. Add your products and opening receivables, then open a cash session.</p><div class="spacer">${button('Set up my store','setup','','arrow')}</div></section><section class="panel list-panel"><h2>What comes next</h2><div class="row"><span>Secure owner and cashier accounts</span><span class="pill warn">Production stage</span></div><div class="row"><span>Cloud backup & multi-device sync</span><span class="pill warn">Production stage</span></div><div class="row"><span>Partial returns & supplier payments</span><span class="pill warn">Planned</span></div><div class="row"><span>Registered tax invoicing</span><span class="pill warn">Separate rollout</span></div></section></div>`;}
// ---------- Sell screen ----------
const unitGrams=(p,unit)=>unit==='sack'?p.sackGrams:1000;
const linePrice=(line,p)=>Math.round(line.quantity*(line.unit==='sack'?p.sackPrice:p.price)/unitGrams(p,line.unit));
const productOf=line=>state.products.find(p=>p.id===line.productId);
function cartTotal(){return cart.reduce((a,x)=>a+linePrice(x,productOf(x)),0);}
function amountText(line,p){if(line.unit!=='sack')return `${qty(line.quantity)} kg`;const sacks=line.quantity/p.sackGrams;return `${count(sacks)} sack${sacks===1?'':'s'} · ${qty(line.quantity)} kg`;}
function toneOf(p){return [...p.id].reduce((a,c)=>a+c.charCodeAt(0),0)%TILE_TONES;}
function productThumb(p,cls){const src=photoOf(photos,p.id);return `<span class="thumb ${cls} ${src?'has-photo':'tone-'+toneOf(p)}">${src?`<img src="${src}" alt="">`:icon('grain')}</span>`;}
function orderLine(line,i){const p=productOf(line),step=unitGrams(p,line.unit);return `<div class="order-line">${productThumb(p,'line-thumb')}<button class="line-info" data-action="edit-cart" data-index="${i}" aria-label="Change amount of ${e(p.name)}"><strong>${e(p.name)}</strong><small>${amountText(line,p)}</small></button><strong class="line-price">${money(linePrice(line,p))}</strong><div class="stepper"><button class="step" data-action="step-cart" data-index="${i}" data-step="-1" aria-label="One less" ${line.quantity<=step?'disabled':''}>${icon('minus')}</button><button class="step" data-action="step-cart" data-index="${i}" data-step="1" aria-label="One more">${icon('plus')}</button></div><button class="icon-btn remove" data-action="remove-cart" data-index="${i}" aria-label="Remove ${e(p.name)}">${icon('trash')}</button></div>`;}
function pos(){const categories=[ALL_PRODUCTS,...new Set(state.products.map(p=>p.category))],products=state.products.filter(p=>(category===ALL_PRODUCTS||p.category===category)&&(p.name+' '+p.sku).toLowerCase().includes(search.toLowerCase())),total=cartTotal(),items=`${cart.length} item${cart.length===1?'':'s'}`;
 const sessionNotice=currentSession(state)?'':`<div class="notice session-closed"><div><strong>Open the cash box first · Buksan ang kaha</strong><span>Count the change money in the drawer before the first sale.</span></div>${button('Open cash box','open','','arrow')}</div>`;
 const tiles=products.map(p=>{const line=cart.find(x=>x.productId===p.id),out=!p.stock,low=!out&&p.stock<=p.minimum;return `<button class="product-tile ${line?'in-cart':''}" data-action="add-to-cart" data-id="${p.id}" ${out?'disabled':''}>${productThumb(p,'tile-thumb')}<strong class="tile-name">${e(p.name)}</strong><span class="tile-price">${money(p.price)}<small> / kg</small></span><span class="tile-stock ${out||low?'warn':''}">${out?'Out of stock · Ubos na':`${qty(p.stock)} kg left${low?' · Low':''}`}</span>${line?`<span class="tile-badge">${icon('check')} ${amountText(line,p)}</span>`:''}</button>`;}).join('')||(state.products.length?'<div class="empty">No rice matches your search.</div>':`<div class="empty"><strong>No rice yet.</strong><br>Add your rice first, then come back to sell.<br><br>${button('Add rice in Stocks','inventory','','box')}</div>`);
 const lines=cart.length?cart.map(orderLine).join(''):`<div class="empty">${icon('cart')}<br><strong>Tap a rice to start.</strong><br><span lang="tl">Pindutin ang bigas para magsimula.</span></div>`;
 return `${sessionNotice}<div class="sell"><section class="shelf" aria-label="Products"><div class="shelf-top"><div class="search">${icon('search')}<input id="search" placeholder="Search rice · Hanapin" aria-label="Search products" value="${e(search)}"></div>${button('Sales today','history','secondary','receipt')}</div><div class="filters">${categories.map(c=>`<button class="filter ${c===category?'active':''}" data-category="${e(c)}">${e(c)}</button>`).join('')}</div><div class="product-grid">${tiles}</div></section><section class="order" id="checkout" aria-label="Current order"><div class="order-head"><h2>Order <small lang="tl">· Bilihin</small></h2><span>${items}</span></div><div class="order-lines">${lines}</div><div class="order-foot"><div class="order-total"><span>Total</span><strong>${money(total)}</strong></div><div class="order-actions">${held?button('Resume · Ibalik','resume','secondary','clock'):button('Hold · Itabi','hold','secondary','clock')}${button('Clear · Burahin','clear-cart','secondary','trash')}</div><button class="btn pay-btn" data-action="checkout" ${!cart.length||!currentSession(state)?'disabled':''}>${icon('cash')} Checkout · Bayad</button><p class="order-note">Internal sales record · Not a tax invoice</p></div></section></div>${cart.length?`<button class="btn mobile-checkout" data-action="go-checkout">${icon('cart')} ${items} · ${money(total)} · See order</button>`:''}`;}
// onSubmit may return a function; it runs after the dialog closes (e.g. to show the receipt).
// variant is a CSS class for larger dialogs such as the keypad and checkout.
function modal(title,body,onSubmit,submit='Save',variant=''){const dialog=$('#modal');dialog.className=variant;dialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="dismiss" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${onSubmit?'<form id="modal-form">':''}${body}<div class="error" id="modal-error" role="alert"></div><div class="modal-actions">${button(onSubmit?'Cancel':'Close','dismiss','secondary')}${onSubmit?`<button class="btn" type="submit">${submit}</button>`:''}</div>${onSubmit?'</form>':''}</div>`;dialog.showModal();dialog.querySelectorAll('[data-action="dismiss"]').forEach(b=>b.onclick=()=>dialog.close());if(onSubmit)$('#modal-form').onsubmit=async ev=>{ev.preventDefault();if(busy)return;busy=true;const submit=ev.target.querySelector('[type="submit"]');submit.disabled=true;try{const after=await onSubmit(Object.fromEntries(new FormData(ev.target)),ev.target);dialog.close();render();if(typeof after==='function')after();}catch(err){$('#modal-error').textContent=err.message;}finally{busy=false;submit.disabled=false;}};}
const productOptions=()=>state.products.map(p=>[p.id,p.name]);
const paymentFields=()=>select('Payment method','method',['Cash','GCash','Maya','Bank Transfer'])+field('Payment reference (for digital payments)','reference')+check('I verified the digital payment in the store’s account.','verified');
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const csvCell=x=>'"'+String(x??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';
function csv(name,headers,rows){download(name,'\uFEFF'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');}
function backup(){download(`storepos-backup-${day()}.json`,JSON.stringify(state,null,2),'application/json');}
function receipt(id){const s=state.sales.find(x=>x.id===id);modal('Transaction summary',`<div class="receipt"><h2>${e(state.store.name)}</h2><p>${e(state.store.address)}</p><p>${s.ref} · ${date(s.at)} ${time(s.at)}</p><p>Cashier: ${e(s.actor)} · ${e(state.customers.find(c=>c.id===s.customerId)?.name||'Walk-in customer')}</p>${s.items.map(x=>`<div class="row"><span>${e(x.name)}<br>${qty(x.quantity)} kg</span><strong>${money(x.revenue)}</strong></div>`).join('')}<div class="row"><span>Discount</span><strong>${money(s.discount)}</strong></div><div class="row"><span>Total</span><strong>${money(s.total)}</strong></div><div class="row"><span>Remaining utang</span><strong>${money(saleDebt(s))}</strong></div><p>${s.refunded?'REFUNDED':''}</p><div class="notice">INTERNAL TRANSACTION SUMMARY<br>Not a BIR-registered invoice or tax document.</div></div><div class="spacer">${button('Print / Save PDF','print','secondary','receipt')}</div>`);$('#modal [data-action="print"]').onclick=()=>window.print();}
async function action(name,el){const id=el?.dataset.id;
 if(online){if(['restore','setup'].includes(name))throw Error('Online store replacement is an administrator recovery operation. Use the Apps Script setup guide.');if(cloudUser.role==='cashier'&&['dashboard','inventory','purchases','reports','settings','product','customer','adjust','purchase','receive','refund','expense','cash-move','profile','audit','movements','backup','export-sales','export-stock','export-statement'].includes(name))throw Error('This action requires owner access.');}
 if(nav.some(x=>x[0]===name)||name==='history'){page=name;search='';render();window.scrollTo(0,0);return;}
 if(name==='menu'){const opened=$('.sidebar').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',String(opened));$('.mobile-menu').setAttribute('aria-label',opened?'Close navigation':'Open navigation');return;}
 if(name==='go-checkout'){$('#checkout').scrollIntoView({behavior:'smooth'});return;}
 if(name==='product')modal('Add a rice product',field('Product name','name','text','','required')+`<div class="fields">${field('SKU / code','sku','text','','required')}${field('Category','category','text','Everyday rice','required')}</div><div class="fields">${num('Selling price / kg (₱)','price','58')}${num('Opening cost / kg (₱)','cost','50')}</div><div class="fields">${num('Opening stock (kg)','stock','0','.001')}${num('Low stock threshold (kg)','minimum','30','.001')}</div><div class="fields">${num('Kilograms per sack','sackGrams','50','.001')}${num('Selling price / sack (₱)','sackPrice','2800')}</div><p class="subtitle">Opening stock is recorded as an opening balance, not a purchase.</p>`,async d=>{await commit('product',{...d,price:scaled(d.price),cost:scaled(d.cost),stock:scaled(d.stock,3),minimum:scaled(d.minimum,3),sackGrams:scaled(d.sackGrams,3),sackPrice:scaled(d.sackPrice)});toast('Product added.');});
 if(name==='customer')modal('Add a customer',field('Customer name','name','text','','required')+field('Contact number (optional)','phone','tel')+num('Existing utang / Opening balance (₱)','opening')+num('Credit limit (₱) · 0 means no limit','limit','5000'),async d=>{await commit('customer',{...d,opening:scaled(d.opening),limit:scaled(d.limit)});toast('Customer added.');});
 if(name==='open')modal('Open your cash session',`<p class="subtitle" style="margin-bottom:20px">Enter the physical cash available for giving change.</p>${num('Opening cash (₱)','amount','1000')}`,async d=>{await commit('open',{amount:scaled(d.amount)});toast('Your cash session is open.');},'Open session');
 if(name==='close')modal('Close the cash session',`<div class="notice green">Expected physical cash: <strong>${money(expectedCash(state))}</strong></div>${num('Actual cash counted (₱)','actual')}<div class="field"><label for="f-reason">Explanation for any shortage or overage</label><textarea id="f-reason" name="reason" rows="3"></textarea></div><p class="subtitle">This preserves your closing count. Further transactions require a new session.</p>`,async d=>{await commit('close',{actual:scaled(d.actual),reason:d.reason});toast('Cash session closed and recorded.');},'Close session');
 if(name==='expense')modal('Record an operating expense',select('Category','category',['Transportation','Rent','Electricity','Labor','Packaging','Maintenance','Utilities','Miscellaneous'])+num('Amount (₱)','amount')+field('Description','description','text','','required')+select('Payment source','source',['Register','External']),async d=>{await commit('expense',{...d,amount:scaled(d.amount)});toast('Expense recorded.');});
 if(name==='cash-move')modal('Cash in / cash out',select('Movement','direction',[['in','Add cash to register'],['out','Withdraw cash from register']])+num('Amount (₱)','amount')+field('Reason','reason','text','','required')+'<p class="subtitle">Cash movements are separate from sales and operating expenses.</p>',async d=>{await commit('cash',{...d,amount:scaled(d.amount)});toast('Cash movement recorded.');});
 if(name==='adjust'){const p=state.products.find(x=>x.id===id);modal('Count & adjust stock',`<div class="notice">${e(p.name)} · Recorded stock: ${qty(p.stock)} kg</div>${num('Actual stock counted (kg)','actual',p.stock/1000,'.001')}${field('Reason for adjustment','reason','text','','required')}`,async d=>{await commit('adjust',{productId:id,actual:scaled(d.actual,3),reason:d.reason});toast('Stock adjustment recorded.');});}
 if(name==='purchase')modal('Create a purchase order',select('Product','productId',productOptions())+field('Supplier name','supplier','text','','required')+field('Supplier invoice / reference (optional)','reference')+`<div class="fields">${num('Number of sacks','sacks','2','1')}${num('Kilograms per sack','sackGrams','50','.001')}</div>`+num('Purchase cost per sack (₱)','costPerSack','2500')+'<p class="subtitle">Save the order now, then receive it when the goods arrive.</p>',async d=>{await commit('purchase',{...d,sacks:scaled(d.sacks,0),sackGrams:scaled(d.sackGrams,3),costPerSack:scaled(d.costPerSack)});toast('Purchase order saved. Receive it to add stock.');},'Save purchase');
 if(name==='receive'){const p=state.purchases.find(x=>x.id===id);modal('Receive purchased stock',`<div class="notice green">${e(p.productName)}<br>${p.sacks} sacks · ${qty(p.quantity)} kg · ${money(p.total)}</div>${select('Payment source','source',[['External','Paid outside the register'],['Register','Pay from the cash register'],['Unpaid','Unpaid — supplier balance']])}<p class="subtitle">This pilot receives the entire order at once. Supplier payment settlement will be added in a later version.</p>`,async d=>{await commit('receive',{purchaseId:id,source:d.source});toast('Stock received and average cost updated.');},'Receive stock');}
 if(name==='collection'){const c=state.customers.find(x=>x.id===id);modal('Collect an utang payment',`<div class="notice green">${e(c.name)} · Outstanding: ${money(balance(state,id))}</div>${num('Amount collected (₱)','amount')}${paymentFields()}`,async d=>{await commit('collection',{...d,customerId:id,amount:scaled(d.amount),verified:d.verified==='on'});toast('Payment collected. No new sale was created.');},'Record collection');}
 if(name==='statement'){const c=state.customers.find(x=>x.id===id),entries=state.ledger.filter(x=>x.customerId===id);modal(e(c.name)+' · Statement',`<div class="notice green">Outstanding: <strong>${money(balance(state,id))}</strong></div>${table(['Date','Entry','Amount'],entries.map(x=>row([date(x.at),x.kind,money(x.amount)])))}<div class="spacer">${button('Export statement','export-statement','secondary','down')}</div>`);$('#modal [data-action="export-statement"]').onclick=()=>csv('customer-statement.csv',['Date','Customer','Type','Amount PHP'],entries.map(x=>[x.at,c.name,x.kind,(x.amount/100).toFixed(2)]));}
 if(name==='refund'){const s=state.sales.find(x=>x.id===id);modal('Refund the full sale',`<div class="notice">${s.ref} · ${money(s.total)}<br>Collected payments will be reversed to their recorded methods. Outstanding utang will be cancelled. Confirm that you have returned any money owed to the customer.</div>${field('Refund reason','reason','text','','required')}${check('Returned rice is suitable for resale. Add it back to inventory.','restock')}${check('I have completed the required cash or digital refunds.','confirmed')}`,async d=>{if(!d.confirmed)throw Error('Confirm that the customer’s refund has been made.');await commit('refund',{saleId:id,reason:d.reason,restock:d.restock==='on'});toast('Refund recorded. Original sale preserved.');},'Record refund');}
 if(name==='receipt')receipt(id);
 // Tapping a rice already in the order edits that line instead of adding a second one.
 if(name==='add-to-cart'||name==='edit-cart'){const index=name==='edit-cart'?Number(el.dataset.index):cart.findIndex(x=>x.productId===id);weightPad(state.products.find(p=>p.id===(cart[index]?.productId||id)),index);}
 if(name==='step-cart'){const index=Number(el.dataset.index),line=cart[index],p=productOf(line),next=line.quantity+Number(el.dataset.step)*unitGrams(p,line.unit);if(next<=0)return;if(next>p.stock)throw Error(`Only ${qty(p.stock)} kg of ${p.name} left.`);cart[index]={...line,quantity:next};render();}
 if(name==='remove-cart'){cart.splice(Number(el.dataset.index),1);render();}
 if(name==='clear-cart'){if(!cart.length)return;modal('Clear this order?',`<p class="subtitle">All ${cart.length} item${cart.length===1?'':'s'} will be removed from the order. Nothing is saved yet.</p>`,async()=>{cart=[];cartId=uid();},'Yes, clear it');}
 if(name==='checkout')checkoutPad();
 if(name==='photo')photoPad(state.products.find(p=>p.id===id));
 if(name==='hold'){if(!cart.length)throw Error('Add items before holding a sale.');if(held)throw Error('Resume the existing held sale first.');held=structuredClone(cart);cart=[];cartId=uid();render();toast('Basket held for this visit. Stock is not reserved.');}
 if(name==='resume'){if(cart.length)throw Error('Clear your current basket before resuming.');cart=held;held=null;cartId=uid();render();}
 if(name==='profile')modal('Your store profile',field('Store name','name','text',state.store.name,'required')+field('Owner name','owner','text',state.store.owner)+field('Business address','address','text',state.store.address),async d=>{await commit('profile',d);toast('Store profile updated.');});
 if(name==='setup')modal('Set up your own store',`<div class="notice">This replaces the current store on this device. A backup will download first. Keep that file to restore these records.</div>${field('Store name','name','text','','required')}${field('Owner name','owner','text','','required')}${field('Business address','address')}${check('I understand that this starts a new empty store.','confirmed')}`,async d=>{if(!d.confirmed)throw Error('Confirm before replacing the current store.');backup();let next=transact(emptyState(),'profile',d);next.revision=state.revision+1;await save(db,next,state.revision);state=next;cart=[];held=null;cartId=uid();page='inventory';toast('Store created. Add your opening products, then customers.');},'Create my store');
 if(name==='backup')backup();
 if(name==='restore')modal('Restore a store backup',`<div class="notice">Restoring replaces the store on this browser. The current store will download as a backup first.</div>${field('StorePOS JSON backup','backup','file','','accept=".json" required')}${check('Replace the current store with the selected backup.','confirmed')}`,async(d,form)=>{if(!d.confirmed)throw Error('Confirm the replacement first.');const file=form.elements.backup.files[0];if(file.size>20e6)throw Error('This backup is too large.');const next=JSON.parse(await file.text());validateBackup(next);backup();next.revision=state.revision+1;await save(db,next,state.revision);state=next;cart=[];held=null;cartId=uid();toast('Backup restored.');},'Restore backup');
 if(name==='audit')modal('Recorded owner activity',table(['Date','Action','User'],[...state.audit].reverse().slice(0,100).map(x=>row([date(x.at)+' '+time(x.at),e(x.action),e(x.actor)]))));
 if(name==='movements')modal('Inventory movement history',table(['Product','Change (kg)','Reason'],[...state.movements].reverse().slice(0,100).map(x=>row([e(state.products.find(p=>p.id===x.productId)?.name||'Unknown'),qty(x.quantity),`${e(x.reason)}<small>${date(x.at)} · ${time(x.at)}</small>`]))));
 if(name==='filter-reports'){const from=$('[name="from"]').value,to=$('[name="to"]').value;if(!from||!to||from>to)throw Error('Choose a valid start and end date.');reportFrom=from;reportTo=to;render();}
 if(name==='export-stock')csv('storepos-inventory.csv',['SKU','Product','Quantity kg','Average cost PHP/kg','Selling price PHP/kg','Stock value PHP'],state.products.map(p=>[p.sku,p.name,p.stock/1000,(p.stock?Math.round(p.stockValue*1000/p.stock):p.cost)/100,p.price/100,p.stockValue/100]));
 if(name==='export-sales')csv('storepos-sales.csv',['Reference','Date','Revenue PHP','Historical COGS PHP','Discount PHP','Outstanding PHP','Refunded'],metrics(state,reportFrom,reportTo).sales.map(s=>[s.ref,s.at,s.total/100,s.cost/100,s.discount/100,saleDebt(s)/100,s.refunded]));
}
function validateBackup(s){if(s?.schema!==1||!s.store||typeof s.store.name!=='string'||typeof s.store.owner!=='string')throw Error('This is not a supported StorePOS backup.');for(const key of ['products','customers','sales','payments','ledger','movements','purchases','expenses','sessions','cashMoves','refunds','audit','processed'])if(!Array.isArray(s[key]))throw Error('Backup is missing '+key);const ids=new Set();for(const p of s.products){if(!p.id||ids.has(p.id)||!['name','sku','category'].every(k=>typeof p[k]==='string')||!['stock','stockValue','price','cost','minimum','sackPrice','sackGrams'].every(k=>Number.isSafeInteger(p[k])&&p[k]>=0)||!p.sackGrams)throw Error('Backup contains invalid product data.');ids.add(p.id);}for(const c of s.customers)if(typeof c.name!=='string'||!Number.isSafeInteger(c.limit)||c.limit<0)throw Error('Backup contains invalid customer data.');for(const key of ['payments','ledger','expenses','cashMoves'])for(const r of s[key])if(!Number.isSafeInteger(r.amount)||!Number.isFinite(Date.parse(r.at)))throw Error('Backup contains invalid financial records.');for(const sale of s.sales)if(!Array.isArray(sale.items)||!Number.isSafeInteger(sale.total)||!Number.isSafeInteger(sale.cost)||!Number.isFinite(Date.parse(sale.at))||sale.items.some(x=>!ids.has(x.productId)||!Number.isSafeInteger(x.quantity)||x.quantity<=0||!Number.isSafeInteger(x.cost)||!Number.isSafeInteger(x.revenue)))throw Error('Backup contains invalid sales records.');if(s.sessions.filter(x=>!x.closedAt).length>1)throw Error('Backup contains overlapping cash sessions.');}
// ---------- Weight keypad: "how much rice?" ----------
const padValue=n=>String(+n.toFixed(PAD_MAX_DECIMALS));
const padLabel=n=>n===.5?'½':padValue(n);
function weightPad(p,index){const existing=cart[index];let unit=existing?.unit||'kg',entry=existing?padValue(existing.quantity/unitGrams(p,unit)):'1',fresh=true;
 const keys=['1','2','3','4','5','6','7','8','9','.','0'].map(k=>`<button type="button" data-key="${k}">${k}</button>`).join('');
 modal(e(p.name),`<div class="pad-product">${productThumb(p,'pad-thumb')}<div><strong>${money(p.price)} / kg</strong><small>${money(p.sackPrice)} per ${qty(p.sackGrams)} kg sack · ${qty(p.stock)} kg left</small></div></div><div class="unit-switch" role="group" aria-label="Sell by"><button type="button" data-unit="kg">By kilo · Kilo</button><button type="button" data-unit="sack">By sack · Sako</button></div><input type="hidden" name="unit"><input type="hidden" name="quantity"><output class="pad-display" aria-live="polite"><span class="pad-amount"></span><span class="pad-price"></span></output><div class="pad-quick"></div><div class="keypad">${keys}<button type="button" data-key="back" aria-label="Erase">${icon('backspace')}</button></div>`,async d=>{const grams=Math.round(scaled(d.quantity,PAD_MAX_DECIMALS)*unitGrams(p,d.unit)/1000);if(!grams||grams>p.stock)throw Error(`Enter an amount up to ${qty(p.stock)} kg.`);const other=cart.findIndex((x,i)=>x.productId===p.id&&i!==index);if(other>=0)throw Error('This rice is already in the order. Change it there.');const line={productId:p.id,quantity:grams,unit:d.unit};if(index>=0)cart[index]=line;else cart.push(line);},existing?'Update order':'Add to order','pad-dialog');
 const dialog=$('#modal'),form=$('#modal-form'),submit=form.querySelector('[type="submit"]'),label=submit.textContent;
 function refresh(){const value=entry.replace(/\.$/,'')||'0',grams=Math.round(scaled(value,PAD_MAX_DECIMALS)*unitGrams(p,unit)/1000),over=grams>p.stock,price=grams?money(linePrice({quantity:grams,unit},p)):'';
  form.unit.value=unit;form.quantity.value=value;
  dialog.querySelectorAll('[data-unit]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.unit===unit)));
  dialog.querySelector('.pad-amount').textContent=unit==='sack'?`${entry} sack${value==='1'?'':'s'}`:`${entry} kg`;
  dialog.querySelector('.pad-price').textContent=over?`Only ${qty(p.stock)} kg left`:price&&`= ${price}`;
  dialog.querySelector('.pad-display').classList.toggle('warn',over);
  submit.disabled=!grams||over;submit.textContent=grams&&!over?`${label} · ${price}`:label;}
 function quick(){dialog.querySelector('.pad-quick').innerHTML=(unit==='sack'?SACK_QUICK.map(n=>[padValue(n),`${n} sack${n===1?'':'s'}`]):KILO_QUICK.map(g=>[padValue(g/1000),`${padLabel(g/1000)} kg`])).map(([v,l])=>`<button type="button" data-quick="${v}">${l}</button>`).join('');}
 // The first key after a quick amount starts a new number; later keys add digits.
 function press(key){if(key==='back'){entry=fresh?'0':entry.slice(0,-1)||'0';}else{if(key==='.'&&!fresh&&entry.includes('.'))return;const next=fresh?(key==='.'?'0.':key):(entry==='0'&&key!=='.'?key:entry+key),decimals=next.split('.')[1]||'';if(decimals.length>PAD_MAX_DECIMALS||next.length>PAD_MAX_LENGTH)return;entry=next;}fresh=false;refresh();}
 dialog.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>press(b.dataset.key));
 dialog.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{if(unit===b.dataset.unit)return;unit=b.dataset.unit;entry='1';fresh=true;quick();refresh();});
 dialog.querySelector('.pad-quick').onclick=ev=>{const b=ev.target.closest('[data-quick]');if(!b)return;entry=b.dataset.quick;fresh=true;refresh();};
 form.onkeydown=ev=>{if(/^[0-9.]$/.test(ev.key))press(ev.key);else if(ev.key==='Backspace')press('back');else return;ev.preventDefault();};
 quick();refresh();submit.focus({preventScroll:true});}

// ---------- Checkout: "how will they pay?" ----------
// Same payment rules as before: cash above the total becomes change, anything unpaid becomes utang.
function paymentsFrom(d,total){if(d.method==='Utang')return [];if(d.method==='Split payment')return [{method:'Cash',amount:scaled(d.cash||'0')},{method:d.digitalMethod,amount:scaled(d.digital||'0'),verified:d.verified==='on',reference:d.reference}];const received=scaled(d.received||'0');return [{method:d.method,amount:d.method==='Cash'?Math.min(received,total):received,verified:d.verified==='on',reference:d.reference}];}
function tenderOf(d){return d.method==='Utang'?0:d.method==='Split payment'?scaled(d.cash||'0')+scaled(d.digital||'0'):scaled(d.received||'0');}
function cashSuggestions(total){return [total,...new Set(CASH_ROUND_UPS.map(step=>Math.ceil(total/step)*step).filter(v=>v>total))];}
function payFields(method,total){const amount=(total/100).toFixed(2),verify=check('I checked the money arrived · Pumasok na','verified');
 if(method==='Cash')return `<label>Customer gave · Bigay ng customer</label><div class="cash-quick">${cashSuggestions(total).map((v,i)=>`<button type="button" data-cash="${(v/100).toFixed(2)}">${i?money(v):'Exact · Sakto'}</button>`).join('')}</div>${num('Cash received ₱','received',amount)}`;
 if(method==='Utang')return '<div class="notice">The whole amount goes to the customer’s utang. Choose the customer above.</div>';
 if(method==='Split payment')return `<div class="fields">${num('Cash ₱','cash','0')}${num('E-wallet or bank ₱','digital',amount)}</div>${select('E-wallet or bank','digitalMethod',DIGITAL_METHODS)}${field('Reference no.','reference')}${verify}`;
 return `${num('Amount received ₱','received',amount)}${field('Reference no. (from their phone)','reference')}${verify}`;}
function checkoutPad(){if(!cart.length)return;const subtotal=cartTotal();
 const summary=cart.map(line=>{const p=productOf(line);return `<div class="sum-line">${productThumb(p,'line-thumb')}<span><strong>${e(p.name)}</strong><small>${amountText(line,p)}</small></span><strong>${money(linePrice(line,p))}</strong></div>`;}).join('');
 modal('Checkout · Bayad',`<div class="checkout-grid"><section class="co-summary"><h3>Order summary</h3>${summary}<div class="sum-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div>${num('Discount ₱ (optional)','discount','0')}<div class="sum-total"><span>Total</span><strong id="co-total">${money(subtotal)}</strong></div></section><section class="co-pay"><h3>How will they pay? <small lang="tl">· Paano magbabayad?</small></h3><div class="pay-methods" role="radiogroup" aria-label="Payment method">${PAY_METHODS.map((m,i)=>`<label class="pay-tile"><input type="radio" name="method" value="${m.value}" ${i?'':'checked'}>${icon(m.icon)}<strong>${m.label}</strong><small>${m.hint}</small></label>`).join('')}</div>${select('Customer · Suki','customerId',[['','Walk-in · No name'],...state.customers.map(c=>[c.id,c.name])])}<div id="pay-fields"></div><div id="due-wrap" hidden>${field('Pay the rest by · Babayaran sa','dueDate','date',day())}</div><div id="pay-result" class="pay-result" aria-live="polite"></div></section></div>`,async d=>{const discount=scaled(d.discount||'0'),total=subtotal-discount,saleId=cartId;await commit('sale',{items:cart,discount,payments:paymentsFrom(d,total),customerId:d.customerId,dueDate:d.dueDate},saleId);cart=[];cartId=uid();return ()=>{toast('Sale saved. Stock and balances updated.');receipt(saleId);};},'Done · Tapos na','checkout-dialog');
 const form=$('#modal-form'),formData=()=>Object.fromEntries(new FormData(form));let typed=false;
 const totalNow=()=>{try{return Math.max(0,subtotal-scaled(formData().discount||'0'));}catch{return subtotal;}};
 function preview(){const d=formData(),out=$('#pay-result');try{const total=subtotal-scaled(d.discount||'0');if(total<0)throw Error();$('#co-total').textContent=money(total);const tender=tenderOf(d),unpaid=total-tender;$('#due-wrap').hidden=unpaid<=0;
   if(unpaid>0){out.className='pay-result warn';out.innerHTML=`<span>${d.method==='Utang'?'Utang · Listahan':'Unpaid · Kulang'}</span><strong>${money(unpaid)}</strong><small>${d.customerId?'Goes to this customer’s utang.':'Choose the customer above.'}</small>`;}
   else if(d.method==='Cash'){out.className='pay-result';out.innerHTML=`<span>Change · Sukli</span><strong>${money(tender-total)}</strong>`;}
   else if(tender>total){out.className='pay-result warn';out.innerHTML=`<span>More than the total</span><strong>${money(tender-total)}</strong><small>Check the amounts.</small>`;}
   else{out.className='pay-result';out.innerHTML=`<span>Fully paid · Bayad na</span><strong>${money(total)}</strong>`;}}
  catch{out.className='pay-result warn';out.innerHTML='<span>Check the amounts you typed.</span>';}}
 function showFields(){$('#pay-fields').innerHTML=payFields(formData().method,totalNow());typed=false;form.querySelectorAll('[data-cash]').forEach(b=>b.onclick=()=>{form.received.value=b.dataset.cash;typed=true;form.querySelectorAll('[data-cash]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));preview();});preview();}
 // Until the cashier types an amount, the amount received follows the total (e.g. after a discount).
 form.oninput=ev=>{const name=ev.target.name;if(name==='method'||(name==='discount'&&!typed))return showFields();if(['received','cash','digital'].includes(name))typed=true;preview();};
 showFields();form.querySelector('[type="submit"]').focus({preventScroll:true});}

